#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    scanf("%d", &n);
    vector<vector<int>> g(n, vector<int>(n));
    for (auto &row : g)
        for (auto &x : row) scanf("%d", &x);
    if (g[0][0] < 0 || g[n - 1][n - 1] < 0) {
        puts("0");
        return 0;
    }
    const int NEG = -1000000000;
    // Two walkers move together; after `step` moves, walker rows a and b fix their columns.
    vector<vector<int>> dp(n, vector<int>(n, NEG)), nxt(n, vector<int>(n));
    dp[0][0] = g[0][0];
    for (int step = 1; step < 2 * n - 1; step++) {
        for (auto &row : nxt) fill(row.begin(), row.end(), NEG);
        int lo = max(0, step - n + 1), hi = min(n - 1, step);
        for (int a = lo; a <= hi; a++) {
            if (g[a][step - a] < 0) continue;
            for (int b = lo; b <= hi; b++) {
                if (g[b][step - b] < 0) continue;
                int v = dp[a][b];
                if (a) v = max(v, dp[a - 1][b]);
                if (b) v = max(v, dp[a][b - 1]);
                if (a && b) v = max(v, dp[a - 1][b - 1]);
                // A shared cell's passenger is counted once.
                if (v >= 0) nxt[a][b] = v + g[a][step - a] + (a != b ? g[b][step - b] : 0);
            }
        }
        swap(dp, nxt);
    }
    printf("%d\n", max(0, dp[n - 1][n - 1]));
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[][] g = new int[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) g[i][j] = nextInt();
        if (g[0][0] < 0 || g[n - 1][n - 1] < 0) {
            System.out.println(0);
            return;
        }
        final int NEG = -1000000000;
        // Two walkers move together; after `step` moves, walker rows a and b fix their columns.
        int[][] dp = new int[n][n], nxt = new int[n][n];
        for (int[] row : dp) Arrays.fill(row, NEG);
        dp[0][0] = g[0][0];
        for (int step = 1; step < 2 * n - 1; step++) {
            for (int[] row : nxt) Arrays.fill(row, NEG);
            int lo = Math.max(0, step - n + 1), hi = Math.min(n - 1, step);
            for (int a = lo; a <= hi; a++) {
                if (g[a][step - a] < 0) continue;
                for (int b = lo; b <= hi; b++) {
                    if (g[b][step - b] < 0) continue;
                    int v = dp[a][b];
                    if (a > 0) v = Math.max(v, dp[a - 1][b]);
                    if (b > 0) v = Math.max(v, dp[a][b - 1]);
                    if (a > 0 && b > 0) v = Math.max(v, dp[a - 1][b - 1]);
                    // A shared cell's passenger is counted once.
                    if (v >= 0) nxt[a][b] = v + g[a][step - a] + (a != b ? g[b][step - b] : 0);
                }
            }
            int[][] tmp = dp;
            dp = nxt;
            nxt = tmp;
        }
        System.out.println(Math.max(0, dp[n - 1][n - 1]));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	g := make([][]int, n)
	for i := range g {
		g[i] = make([]int, n)
		for j := range g[i] {
			g[i][j] = int(nextInt())
		}
	}
	if g[0][0] < 0 || g[n-1][n-1] < 0 {
		fmt.Println(0)
		return
	}
	const NEG = -1000000000
	grid := func() [][]int {
		m := make([][]int, n)
		for i := range m {
			m[i] = make([]int, n)
			for j := range m[i] {
				m[i][j] = NEG
			}
		}
		return m
	}
	// Two walkers move together; after `step` moves, walker rows a and b fix their columns.
	dp, nxt := grid(), grid()
	dp[0][0] = g[0][0]
	for step := 1; step < 2*n-1; step++ {
		for i := range nxt {
			for j := range nxt[i] {
				nxt[i][j] = NEG
			}
		}
		lo, hi := max(0, step-n+1), min(n-1, step)
		for a := lo; a <= hi; a++ {
			if g[a][step-a] < 0 {
				continue
			}
			for b := lo; b <= hi; b++ {
				if g[b][step-b] < 0 {
					continue
				}
				v := dp[a][b]
				if a > 0 {
					v = max(v, dp[a-1][b])
				}
				if b > 0 {
					v = max(v, dp[a][b-1])
				}
				if a > 0 && b > 0 {
					v = max(v, dp[a-1][b-1])
				}
				// A shared cell's passenger is counted once.
				if v >= 0 {
					nxt[a][b] = v + g[a][step-a]
					if a != b {
						nxt[a][b] += g[b][step-b]
					}
				}
			}
		}
		dp, nxt = nxt, dp
	}
	fmt.Println(max(0, dp[n-1][n-1]))
}
